// File: src/tests/controllers/article.controller.test.ts
// Integration tests for article controller endpoints to verify readingTime field inclusion

import request from 'supertest';
import { app } from '../../main'; // Adjust import path as needed
import { ArticleService } from '../../app/routes/article/article.service';

describe('Article Controller - readingTime field integration', () => {

  describe('GET /api/articles/:slug', () => {
    it('should include readingTime field in single article response', async () => {
      const response = await request(app)
        .get('/api/articles/test-article-slug')
        .expect(200);

      expect(response.body.article).toBeDefined();
      expect(response.body.article.readingTime).toBeDefined();
      expect(typeof response.body.article.readingTime).toBe('number');
      expect(response.body.article.readingTime).toBeGreaterThanOrEqual(1);
    });

    it('should calculate readingTime correctly for article with known word count', async () => {
      // Assuming test article has ~400 words, should return 2 minutes
      const response = await request(app)
        .get('/api/articles/article-with-400-words')
        .expect(200);

      expect(response.body.article.readingTime).toBe(2);
    });

    it('should return minimum 1 minute readingTime for short articles', async () => {
      // Test with article having < 200 words
      const response = await request(app)
        .get('/api/articles/short-article')
        .expect(200);

      expect(response.body.article.readingTime).toBe(1);
    });
  });

  describe('GET /api/articles', () => {
    it('should include readingTime field for all articles in list response', async () => {
      const response = await request(app)
        .get('/api/articles')
        .expect(200);

      expect(response.body.articles).toBeDefined();
      expect(Array.isArray(response.body.articles)).toBe(true);

      response.body.articles.forEach((article: any) => {
        expect(article.readingTime).toBeDefined();
        expect(typeof article.readingTime).toBe('number');
        expect(article.readingTime).toBeGreaterThanOrEqual(1);
      });
    });

    it('should include readingTime with query filters applied', async () => {
      const response = await request(app)
        .get('/api/articles?tag=testing&limit=5')
        .expect(200);

      expect(response.body.articles.length).toBeGreaterThan(0);
      response.body.articles.forEach((article: any) => {
        expect(article.readingTime).toBeDefined();
      });
    });
  });

  describe('GET /api/articles/feed', () => {
    it('should include readingTime field for all articles in feed response', async () => {
      // Requires authentication token
      const authToken = 'Bearer test-jwt-token'; // Replace with valid test token

      const response = await request(app)
        .get('/api/articles/feed')
        .set('Authorization', authToken)
        .expect(200);

      expect(response.body.articles).toBeDefined();
      expect(Array.isArray(response.body.articles)).toBe(true);

      response.body.articles.forEach((article: any) => {
        expect(article.readingTime).toBeDefined();
        expect(typeof article.readingTime).toBe('number');
        expect(article.readingTime).toBeGreaterThanOrEqual(1);
      });
    });

    it('should include readingTime with pagination parameters', async () => {
      const authToken = 'Bearer test-jwt-token';

      const response = await request(app)
        .get('/api/articles/feed?limit=10&offset=0')
        .set('Authorization', authToken)
        .expect(200);

      response.body.articles.forEach((article: any) => {
        expect(article.readingTime).toBeDefined();
      });
    });
  });

  describe('Backward compatibility', () => {
    it('should still include all existing article fields along with readingTime', async () => {
      const response = await request(app)
        .get('/api/articles/test-article-slug')
        .expect(200);

      const article = response.body.article;

      // Verify all existing fields are present
      expect(article.slug).toBeDefined();
      expect(article.title).toBeDefined();
      expect(article.description).toBeDefined();
      expect(article.body).toBeDefined();
      expect(article.tags).toBeDefined();
      expect(article.author).toBeDefined();
      expect(article.favorited).toBeDefined();

      // Verify new field is also present
      expect(article.readingTime).toBeDefined();
    });
  });

  describe('Edge cases', () => {
    it('should handle articles with null or empty body gracefully', async () => {
      const response = await request(app)
        .get('/api/articles/article-with-empty-body')
        .expect(200);

      expect(response.body.article.readingTime).toBe(1);
    });

    it('should handle articles with exactly 200 words', async () => {
      const response = await request(app)
        .get('/api/articles/article-with-200-words')
        .expect(200);

      expect(response.body.article.readingTime).toBe(1);
    });

    it('should handle articles with 201 words', async () => {
      const response = await request(app)
        .get('/api/articles/article-with-201-words')
        .expect(200);

      expect(response.body.article.readingTime).toBe(2);
    });
  });
});

// Test file: src/tests/services/article.service.test.ts
// Add these test cases to verify readingTime field integration in ArticleService

describe('ArticleService - readingTime field', () => {

  it('should include readingTime in article response from getArticleBySlug', async () => {
    // Arrange
    const slug = 'test-article-slug';
    const mockUser = { id: 1, username: 'testuser' };

    // Act
    const article = await articleService.getArticleBySlug(slug, mockUser);
    const serializedArticle = article.toJSONFor(mockUser);

    // Assert
    expect(serializedArticle).toHaveProperty('readingTime');
    expect(typeof serializedArticle.readingTime).toBe('number');
    expect(serializedArticle.readingTime).toBeGreaterThanOrEqual(1);
  });

  it('should include readingTime for all articles in getArticles list', async () => {
    // Arrange
    const query = { limit: 10, offset: 0 };
    const mockUser = { id: 1, username: 'testuser' };

    // Act
    const result = await articleService.getArticles(query, mockUser);

    // Assert
    expect(result.articles).toBeDefined();
    expect(Array.isArray(result.articles)).toBe(true);
    result.articles.forEach(article => {
      const serialized = article.toJSONFor(mockUser);
      expect(serialized).toHaveProperty('readingTime');
      expect(typeof serialized.readingTime).toBe('number');
      expect(serialized.readingTime).toBeGreaterThanOrEqual(1);
    });
  });

  it('should include readingTime for all articles in getFeed', async () => {
    // Arrange
    const mockUser = { id: 1, username: 'testuser' };
    const limit = 20;
    const offset = 0;

    // Act
    const feedArticles = await articleService.getFeed(mockUser, limit, offset);

    // Assert
    expect(Array.isArray(feedArticles)).toBe(true);
    feedArticles.forEach(article => {
      const serialized = article.toJSONFor(mockUser);
      expect(serialized).toHaveProperty('readingTime');
      expect(typeof serialized.readingTime).toBe('number');
      expect(serialized.readingTime).toBeGreaterThanOrEqual(1);
    });
  });

  it('should calculate readingTime correctly for article with 400 words', async () => {
    // Arrange
    const mockArticleBody = Array(400).fill('word').join(' ');
    const mockArticle = {
      slug: 'test-slug',
      body: mockArticleBody,
      toJSONFor: function(user) {
        const wordCount = this.body.split(/\s+/).filter(w => w.length > 0).length;
        const readingTime = Math.ceil(wordCount / 200);
        return { readingTime };
      }
    };

    // Act
    const serialized = mockArticle.toJSONFor(null);

    // Assert
    expect(serialized.readingTime).toBe(2); // 400 words / 200 WPM = 2 minutes
  });

  it('should return minimum 1 minute readingTime for short articles', async () => {
    // Arrange
    const mockArticleBody = 'Short article with less than 200 words';
    const mockArticle = {
      slug: 'short-article',
      body: mockArticleBody,
      toJSONFor: function(user) {
        const wordCount = this.body.split(/\s+/).filter(w => w.length > 0).length;
        const readingTime = Math.max(1, Math.ceil(wordCount / 200));
        return { readingTime };
      }
    };

    // Act
    const serialized = mockArticle.toJSONFor(null);

    // Assert
    expect(serialized.readingTime).toBe(1);
  });

  it('should handle empty or null body gracefully', async () => {
    // Arrange
    const mockArticleWithNullBody = {
      slug: 'null-body-article',
      body: null,
      toJSONFor: function(user) {
        if (!this.body) {
          return { readingTime: 1 };
        }
        const wordCount = this.body.split(/\s+/).filter(w => w.length > 0).length;
        const readingTime = Math.max(1, Math.ceil(wordCount / 200));
        return { readingTime };
      }
    };

    // Act
    const serialized = mockArticleWithNullBody.toJSONFor(null);

    // Assert
    expect(serialized.readingTime).toBe(1);
    expect(() => mockArticleWithNullBody.toJSONFor(null)).not.toThrow();
  });

  it('should verify all existing article fields are still present with readingTime', async () => {
    // Arrange
    const slug = 'complete-article';
    const mockUser = { id: 1, username: 'testuser' };

    // Act
    const article = await articleService.getArticleBySlug(slug, mockUser);
    const serialized = article.toJSONFor(mockUser);

    // Assert - verify backward compatibility
    expect(serialized).toHaveProperty('title');
    expect(serialized).toHaveProperty('slug');
    expect(serialized).toHaveProperty('description');
    expect(serialized).toHaveProperty('body');
    expect(serialized).toHaveProperty('tags');
    expect(serialized).toHaveProperty('author');
    expect(serialized).toHaveProperty('favorited');
    expect(serialized).toHaveProperty('readingTime'); // New field
  });
});

// Test file: src/app/routes/article/article.model.test.ts
// Tests for the new calculateReadingTime() method and readingTime field in toJSONFor()

import { Article } from './article.model';

describe('Article Model - Reading Time Feature', () => {

  describe('calculateReadingTime()', () => {

    it('should calculate reading time correctly for 400 words (2 minutes)', () => {
      const article = new Article();
      // Create a body with exactly 400 words
      article.body = Array(400).fill('word').join(' ');

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(2); // Math.ceil(400/200) = 2
    });

    it('should return minimum 1 minute for articles with fewer than 200 words', () => {
      const article = new Article();
      article.body = 'This is a short article with only ten words here.';

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(1);
    });

    it('should handle null body gracefully and return 1 minute', () => {
      const article = new Article();
      article.body = null;

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(1);
    });

    it('should handle undefined body gracefully and return 1 minute', () => {
      const article = new Article();
      article.body = undefined;

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(1);
    });

    it('should handle empty string body and return 1 minute', () => {
      const article = new Article();
      article.body = '';

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(1);
    });

    it('should calculate reading time for exactly 200 words (1 minute)', () => {
      const article = new Article();
      article.body = Array(200).fill('word').join(' ');

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(1); // Math.ceil(200/200) = 1
    });

    it('should calculate reading time for 201 words (2 minutes)', () => {
      const article = new Article();
      article.body = Array(201).fill('word').join(' ');

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(2); // Math.ceil(201/200) = 2
    });

    it('should calculate reading time for 1000 words (5 minutes)', () => {
      const article = new Article();
      article.body = Array(1000).fill('word').join(' ');

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(5); // Math.ceil(1000/200) = 5
    });

    it('should handle body with multiple spaces and filter empty strings', () => {
      const article = new Article();
      article.body = 'word1   word2     word3'; // Multiple spaces between words

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(1); // Only 3 words, should return minimum 1
    });

    it('should handle body with newlines and tabs', () => {
      const article = new Article();
      article.body = 'word1\n\nword2\t\tword3\nword4';

      const result = article.toJSONFor();

      expect(result.readingTime).toBe(1); // Only 4 words, should return minimum 1
    });
  });

  describe('toJSONFor() - readingTime field integration', () => {

    it('should include readingTime field in the JSON response', () => {
      const article = new Article();
      article.title = 'Test Article';
      article.slug = 'test-article';
      article.description = 'Test description';
      article.body = Array(400).fill('word').join(' ');

      const result = article.toJSONFor();

      expect(result).toHaveProperty('readingTime');
      expect(typeof result.readingTime).toBe('number');
    });

    it('should not break existing fields when adding readingTime', () => {
      const article = new Article();
      article.title = 'Test Article';
      article.slug = 'test-article';
      article.description = 'Test description';
      article.body = 'Test body content';
      article.tags = ['tag1', 'tag2'];

      const result = article.toJSONFor();

      // Verify all existing fields are still present
      expect(result).toHaveProperty('title');
      expect(result).toHaveProperty('slug');
      expect(result).toHaveProperty('description');
      expect(result).toHaveProperty('body');
      expect(result).toHaveProperty('tags');
      expect(result).toHaveProperty('readingTime');
    });

    it('should calculate readingTime consistently across multiple calls', () => {
      const article = new Article();
      article.body = Array(600).fill('word').join(' ');

      const result1 = article.toJSONFor();
      const result2 = article.toJSONFor();

      expect(result1.readingTime).toBe(result2.readingTime);
      expect(result1.readingTime).toBe(3); // Math.ceil(600/200) = 3
    });
  });
});

